    PrimitiveBasis qubits ≃
      Fin 2 × (OtherPrimitiveWires target → Fin 2)

theorem evalPrimitiveGate_dagger {qubits : Nat}
    (gate : PrimitiveGate qubits) :
    evalPrimitiveGate gate.dagger = star (evalPrimitiveGate gate)

